param([string]$BaseUrl="http://127.0.0.1:8000",[int]$ProjectId=1)
$ErrorActionPreference="Stop";function Session([string]$scope){Invoke-RestMethod -Method Post -Uri "$BaseUrl/api/v1/auth/local/demo-session" -ContentType "application/json" -Body (@{scope=$scope}|ConvertTo-Json -Compress)};function Post([string]$path,[hashtable]$payload,[hashtable]$headers){Invoke-RestMethod -Method Post -Uri "$BaseUrl$path" -Headers $headers -ContentType "application/json" -Body ($payload|ConvertTo-Json -Depth 12 -Compress)}
$hq=Session hq;$agency=Session agency;$client=Session client;$hh=@{Authorization="Bearer $($hq.token)"};$ah=@{Authorization="Bearer $($agency.token)"};$ch=@{Authorization="Bearer $($client.token)"};$stamp=Get-Date -Format "yyyyMMddHHmmssfff";$root="/api/v1/factory-platform/projects/$ProjectId/technical-seo"
$audit=Post "$root/audits" @{site_reference="SITE-$stamp";audit_reference="CRAWL-$stamp";public_scope="global"} $hh;$snapshot=Post "$root/audits/$($audit.id)/snapshots" @{evidence_manifest=@{crawl_reference="CRAWL-$stamp";checks=@("robots","sitemap","indexability");finding="review"}} $hh;$snapshot=Post "$root/snapshots/$($snapshot.id)/verify" @{expected_revision=$snapshot.revision;reference="SEO-VERIFY-$stamp"} $ah;$release=Post "$root/snapshots/$($snapshot.id)/releases" @{target="site-owner";remediation_manifest=@{actions=@("review","approve-owner-change");automatic_site_change=$false};rollback_reference="SEO-ROLLBACK-$stamp"} $hh;$release=Post "$root/releases/$($release.id)/approve" @{expected_revision=$release.revision;reference="SEO-APPROVE-$stamp"} $ah;$release=Post "$root/releases/$($release.id)/acknowledge" @{expected_revision=$release.revision;reference="SEO-RECEIPT-$stamp"} $ch;$workspace=Invoke-RestMethod -Method Get -Uri "$BaseUrl$root" -Headers $hh
[pscustomobject]@{project_id=$ProjectId;audit_number=$audit.audit_number;audit_status=$audit.status;snapshot_number=$snapshot.snapshot_number;snapshot_status=$snapshot.status;release_number=$release.release_number;release_status=$release.status;release_available=$release.available;availability=$workspace.availability.status;public_site_mutated_directly=$workspace.contract.public_site_mutated_directly;search_console_credential_stored=$workspace.contract.search_console_credential_stored;search_ranking_guaranteed=$workspace.contract.search_ranking_guaranteed;consumer_handoff_required=$workspace.contract.consumer_handoff_required;evidence_count=$workspace.evidence.Count;hq=$hq.user.id;agency=$agency.user.id;client=$client.user.id}|ConvertTo-Json
